script:
$services = 'LanmanServer','LanmanWorkstation','Spooler'
$original = @()
foreach ($name in $services) {
  $svc = Get-Service -Name $name -ErrorAction SilentlyContinue
  if ($svc) { $original += @{ Name = $name; StartType = $svc.StartType.ToString() } }
}
$original | ConvertTo-Json | Set-Content -Path {{BackupFile}} -Encoding UTF8
foreach ($name in $services) {
  Set-Service -Name $name -StartupType Automatic -ErrorAction SilentlyContinue
  Start-Service -Name $name -ErrorAction SilentlyContinue
}
Write-Output '已启用文件共享与打印相关服务。'
